// App members. All orchestration and ledger writes run on the UI thread.
std::unique_ptr<Auditions> auditionData;std::string auditionScope,auditionChannel,auditionRun;
int auditionSelected=-1;bool auditionRunning=false,auditionInFlight=false;
Auditions& auditions(){if(!auditionData||auditionScope!=store->workspaceScope||auditionChannel!=store->active){auditionRunning=false;auditionInFlight=false;auditionRun.clear();auditionSelected=-1;auditionData=std::make_unique<Auditions>(store->root,store->workspaceScope,store->active);auditionData->recover();auditionScope=store->workspaceScope;auditionChannel=store->active;}return *auditionData;}
json auditionScenes(){save();json scenes=json::array();if(store->hasStoryboard()){auto& board=store->current()["storyboard"];auto& page=boardPage(board,str(board,"active_page"));if(page["panels"].size()>15)throw std::runtime_error("현재 페이지의 컷을 15개 이하로 나눠 주세요.");for(auto& panel:page["panels"])scenes.push_back({{"id",str(panel,"id")},{"page",str(page,"id")},{"name",str(panel,"name")},{"snapshot",panel["snapshot"]}});}else scenes.push_back({{"id",id()},{"page",""},{"name",str(store->current(),"name")},{"snapshot",panelSnapshot(store->state)}});for(auto& scene:scenes){json refs=json::array();for(auto& ref:scene["snapshot"]["project"].value("references",json::array())){auto file=fs::path(wide(str(ref,"path")));if(!fs::is_regular_file(file)||fs::file_size(file)>25*1024*1024)throw std::runtime_error("참조 이미지를 확인하세요.");refs.push_back({{"path",str(ref,"path")},{"sha",sha256(readFile(file))}});}auto initial=str(scene["snapshot"]["settings"],"initial_image");if(!initial.empty()){auto file=fs::path(wide(initial));if(!fs::is_regular_file(file)||fs::file_size(file)>25*1024*1024)throw std::runtime_error("초기 이미지를 확인하세요.");refs.push_back({{"path",initial},{"sha",sha256(readFile(file))}});}scene["files"]=refs;}return scenes;}
void auditionDispatch(){auto& ledger=auditions();if(auditionRun.empty())return;auto& run=ledger.run(auditionRun);if(str(run,"server")!=sha256(str(store->settings,"api"))||str(run,"mode")!=str(store->settings,"content_mode","standard"))throw std::runtime_error("오디션을 만든 서버와 모드로 돌아가세요.");int index=ledger.next(auditionRun);if(index<0){auditionRunning=false;run["state"]="paused";bool complete=true;for(auto& item:run["tasks"])complete&=str(item,"state")=="completed";if(complete)run["state"]="completed";ledger.save();status=complete?L"오디션 완료":L"오디션 종료 · 확인이 필요한 후보가 있습니다.";return;}
 auto item=ledger.task(auditionRun,index),scene=run["scenes"][item.value("scene",0)];for(auto& file:scene.value("files",json::array())){auto path=fs::path(wide(str(file,"path")));if(!fs::is_regular_file(path)||fs::file_size(path)>25*1024*1024||sha256(readFile(path))!=str(file,"sha"))throw std::runtime_error("참조 파일이 바뀌었습니다. 새 오디션을 만드세요.");}auto cfg=store->settings,state=store->state;applyPanelSnapshot(state,scene["snapshot"]);cfg.update(state["settings"]);cfg["count"]="1";cfg["seed"]=std::to_string(item["seed"].get<int64_t>());cfg["channel_id"]=store->active;cfg["channel_name"]=str(store->current(),"name");cfg["creator_name"]=str(accountProfile,"nickname","User");if(!str(scene,"page").empty()){cfg["page_id"]=str(scene,"page");cfg["panel_id"]=str(scene,"id");cfg["panel_snapshot_hash"]=sha256(scene["snapshot"].dump());}else{cfg.erase("page_id");cfg.erase("panel_id");cfg.erase("panel_snapshot_hash");}cfg["_audition_run"]=auditionRun;cfg["_audition_index"]=index;cfg["_audition_job"]=str(item,"job");if(!developer()){cfg["consistency_enabled"]=false;cfg["consistency_profile"]="사용 안 함";cfg["style_profile"]="사용 안 함";}validate(cfg);if(!localOutputAllowed(cfg,fs::path(wide(str(cfg,"output")))))throw std::runtime_error("계정 저장 폴더를 확인하세요.");ledger.start(auditionRun,index);auditionInFlight=true;auditionImagePercent=0;try{engine->enqueue({store->active,str(item,"request"),cfg,state,false});}catch(...){auditionInFlight=false;ledger.terminal(auditionRun,index,false,"등록을 확인하지 못했습니다.");throw;}status=L"오디션 후보 "+std::to_wstring(index+1)+L" / "+std::to_wstring(run["tasks"].size());}
void auditionTick(){if(!auditionRunning&&!auditionInFlight)return;if(auditionScope!=store->workspaceScope||auditionChannel!=store->active){auditionRunning=false;auditionInFlight=false;return;}if(auditionInFlight){bool idle=false;{std::lock_guard lock(engine->mutex);idle=!engine->busy&&engine->tasks.empty()&&engine->events.empty();}if(!idle)return;auto& ledger=auditions();int index=ledger.next(auditionRun);if(index>=0)ledger.terminal(auditionRun,index,false,"실행 상태를 확인하지 못했습니다.");ledger.run(auditionRun)["state"]="paused";ledger.save();auditionRunning=false;auditionInFlight=false;status=L"오디션 일시정지 · 후보 상태를 확인하세요.";return;}if(!auditionRunning||engine->busy||engine->cancelling)return;{std::lock_guard lock(engine->mutex);if(!engine->tasks.empty())return;}try{auditionDispatch();}catch(const std::exception& e){auditionRunning=false;if(auditionData&&!auditionRun.empty()){auditionData->run(auditionRun)["state"]="paused";auditionData->save();}status=wide(userError(e.what()));}}
void auditionReply(const Event& event){if(str(event.data,"scope")!=store->workspaceScope)return;std::unique_ptr<Auditions> other;Auditions* target;if(event.project==store->active)target=&auditions();else{other=std::make_unique<Auditions>(store->root,store->workspaceScope,event.project);target=other.get();}auto& ledger=*target;auto key=str(event.data,"run");auto index=event.data.value("index",-1);if(event.kind=="audition_job")ledger.accepted(key,index,str(event.data,"job"));else if(event.kind=="audition_image"){ledger.image(key,index,str(event.data,"path"));if(event.project==auditionChannel&&key==auditionRun)auditionImagePercent=0;}else if(event.kind=="audition_terminal"){ledger.terminal(key,index,flag(event.data,"success"),str(event.data,"error"));if(event.project==auditionChannel&&key==auditionRun)auditionInFlight=false;if(!flag(event.data,"success")){if(event.project==auditionChannel&&key==auditionRun)auditionRunning=false;ledger.run(key)["state"]="paused";ledger.save();}}}
void auditionPreview(){if(auditionRun.empty()||auditionSelected<0)return;auto& item=auditions().task(auditionRun,auditionSelected);auto path=fs::path(wide(str(item,"path")));if(!fs::is_regular_file(path)||!localOutputAllowed(store->settings,path))throw std::runtime_error("후보 이미지 파일을 확인하세요.");if(str(auditions().run(auditionRun),"mode")!=str(store->settings,"content_mode","standard"))throw std::runtime_error("후보를 만든 모드로 돌아가세요.");select(path);}
void auditionMenu(){if(welcome||str(store->settings,"api_key").empty())throw std::runtime_error("로그인 후 이용하세요.");auto& ledger=auditions();HMENU menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING,1,L"새 오디션 · 현재 페이지");AppendMenuW(menu,MF_STRING|(!auditionRun.empty()?0:MF_GRAYED),2,L"선택 오디션 재개");AppendMenuW(menu,MF_STRING|(auditionRunning?0:MF_GRAYED),3,L"일시정지 · 현재 한 장까지 완료");AppendMenuW(menu,MF_STRING,4,L"진행 확인");std::vector<std::pair<std::string,int>> candidates;for(auto& run:ledger.data["runs"]){HMENU scenes=CreatePopupMenu();for(int si=0;si<int(run["scenes"].size());si++){HMENU list=CreatePopupMenu();for(int i=0;i<int(run["tasks"].size());i++){auto& item=run["tasks"][i];if(item.value("scene",-1)!=si)continue;candidates.emplace_back(str(run,"id"),i);auto state=str(item,"state");std::wstring status=state=="completed"?L"완료":state=="pending"?L"대기":state=="running"?L"진행":state=="uncertain"?L"확인 필요":L"실패";auto title=std::to_wstring(item.value("candidate",0)+1)+L" · "+status+L" · ★"+std::to_wstring(item.value("stars",0));AppendMenuW(list,MF_STRING,1000+candidates.size()-1,title.c_str());}AppendMenuW(scenes,MF_POPUP,(UINT_PTR)list,wide(str(run["scenes"][si],"name")).c_str());}auto title=wide(str(run,"created"))+L" · "+std::to_wstring(run["tasks"].size())+L"장";AppendMenuW(menu,MF_POPUP,(UINT_PTR)scenes,title.c_str());}
 AppendMenuW(menu,MF_SEPARATOR,0,nullptr);for(int stars=1;stars<=5;stars++)AppendMenuW(menu,MF_STRING|(auditionSelected>=0?0:MF_GRAYED),10+stars,(L"평가 · "+std::to_wstring(stars)+L"점").c_str());AppendMenuW(menu,MF_STRING|(auditionSelected>=0?0:MF_GRAYED),20,L"선정본으로 저장");AppendMenuW(menu,MF_STRING|(auditionSelected>=0?0:MF_GRAYED),21,L"비교 기준 A로 지정");AppendMenuW(menu,MF_STRING|(auditionSelected>=0?0:MF_GRAYED),22,L"선택 후보 B와 비교");AppendMenuW(menu,MF_STRING,23,L"비교 종료");POINT point;GetCursorPos(&point);int command=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,point.x,point.y,0,hwnd,nullptr);DestroyMenu(menu);if(!command)return;
 if(command>=1000&&size_t(command-1000)<candidates.size()){if(auditionRunning||auditionInFlight)throw std::runtime_error("현재 후보를 마친 뒤 목록을 바꿔 주세요.");auditionRun=candidates[command-1000].first;auditionSelected=candidates[command-1000].second;if(str(ledger.task(auditionRun,auditionSelected),"state")=="completed")auditionPreview();else status=L"오디션 선택 · 재개 또는 진행 확인을 누르세요.";return;}if(command==3){auditionRunning=false;if(!auditionRun.empty()){ledger.run(auditionRun)["state"]="paused";ledger.save();}status=L"일시정지 · 현재 한 장을 마친 뒤 멈춥니다.";return;}if(command==4){int completed=0,pending=0,unknown=0;for(auto& run:ledger.data["runs"])for(auto& task:run["tasks"]){auto state=str(task,"state");completed+=state=="completed";pending+=state=="pending";unknown+=state=="uncertain"||state=="failed";}status=L"오디션 완료 "+std::to_wstring(completed)+L" · 대기 "+std::to_wstring(pending)+L" · 확인 "+std::to_wstring(unknown);return;}if(command>=11&&command<=15){ledger.rate(auditionRun,auditionSelected,command-10);status=L"평가 저장";return;}if(command==23){stopAuditionComparison();return;}if(command==21){auditionPreview();auditionCompareReference=selected;auditionCompareReferenceRun=auditionRun;auditionCompareReferenceIndex=auditionSelected;auditionCompareScope=store->workspaceScope;auditionCompareChannel=store->active;auditionCompareMode=str(store->settings,"content_mode","standard");status=L"비교 기준 A 저장 · 다른 후보를 선택하세요.";return;}if(command==22){checkAuditionComparison();if(auditionCompareReference.empty()||auditionCompareReferenceRun!=auditionRun||auditionCompareReferenceIndex<0||ledger.task(auditionRun,auditionCompareReferenceIndex).value("scene",-1)!=ledger.task(auditionRun,auditionSelected).value("scene",-2))throw std::runtime_error("같은 장면의 비교 기준 A를 먼저 지정하세요.");auto path=fs::path(wide(str(ledger.task(auditionRun,auditionSelected),"path")));beginAuditionComparison(auditionCompareReference,path);return;}if(command==20){ledger.choose(auditionRun,auditionSelected);status=L"선정본 저장";return;}if(auditionRunning||auditionInFlight||engine->locked(store->active))throw std::runtime_error("현재 생성을 마치거나 일시정지한 뒤 진행하세요.");if(command==1){auto answer=inputBox(hwnd,L"장면당 후보 수 (1~20)",L"20");if(answer.empty())return;size_t parsed=0;int count=std::stoi(answer,&parsed);if(parsed!=answer.size()||count<1||count>20)throw std::runtime_error("1~20 사이 숫자를 입력하세요.");auto scenes=auditionScenes();auto total=scenes.size()*count;if(MessageBoxW(hwnd,(std::to_wstring(total)+L"장을 현재 설정으로 생성할까요?\n사용량은 실제 생성한 장수만큼 차감됩니다.").c_str(),L"오디션 시작",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;auditionRun=ledger.create(scenes,count,str(store->settings,"api"),str(store->settings,"content_mode","standard"));auditionSelected=-1;}if(command==1||command==2){ledger.run(auditionRun)["state"]="running";ledger.save();auditionRunning=true;auditionTick();}}
